let language = safeGet('cc-language') || 'ar';
let theme = safeGet('cc-theme') || 'light';
let currentTopic = safeGet('cc-topic') || 'home';
let glossaryQuery = '';
let glossaryCategory = 'all';
function safeGet(key){try{return localStorage.getItem(key)}catch{return null}}
function safeSet(key,value){try{localStorage.setItem(key,value)}catch{/* Storage may be disabled; app still works. */}}
if(!['ar','en'].includes(language)) language='ar';
if(!['light','dark'].includes(theme)) theme='light';
if(currentTopic!=='home'&&currentTopic!=='glossary'&&!topics.some(x=>x.id===currentTopic)) currentTopic='home';

function tr(value){if(value&&typeof value==='object'&&('ar'in value||'en'in value))return value[language]??value.ar??value.en??'';return value??''}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setTheme(next){theme=next==='dark'?'dark':'light';document.body.dataset.theme=theme;$('#themeIcon').textContent=theme==='dark'?'🌙':'☀️';$('#themeBtn').setAttribute('aria-label',language==='ar'?'تبديل الوضع اللوني':'Toggle color theme');safeSet('cc-theme',theme)}
function setLanguage(next){language=next==='en'?'en':'ar';document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';document.body.dir=document.documentElement.dir;$$('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(ui[language][key])el.textContent=ui[language][key]});$('#arabicBtn').classList.toggle('active',language==='ar');$('#englishBtn').classList.toggle('active',language==='en');$('#studentName').textContent=IDENTITY.student;$('#doctorName').textContent=IDENTITY.doctor;safeSet('cc-language',language);renderNavigation();renderContent()}
function iconSvg(){return `<svg viewBox="0 0 300 220" role="img" aria-label="${language==='ar'?'رسم توضيحي لشبكة سحابية':'Cloud network illustration'}"><defs><linearGradient id="cloudGrad" x1="0" x2="1"><stop stop-color="#37c9ff"/><stop offset="1" stop-color="#2764e9"/></linearGradient></defs><g stroke="#4aa9ff" stroke-width="2" opacity=".65"><path d="M42 150 L94 85 L150 150 L207 80 L258 145 M94 85 L207 80 M42 150 L150 150 L258 145 M94 85 L110 35 L207 80" fill="none"/></g><g fill="#0d3d7a" stroke="#70d6ff" stroke-width="2"><rect x="23" y="135" width="39" height="43" rx="7"/><rect x="83" y="63" width="39" height="43" rx="7"/><rect x="132" y="129" width="39" height="43" rx="7"/><rect x="188" y="59" width="39" height="43" rx="7"/><rect x="239" y="125" width="39" height="43" rx="7"/><rect x="91" y="15" width="39" height="43" rx="7"/></g><g fill="#e8f7ff"><circle cx="42" cy="147" r="4"/><circle cx="42" cy="159" r="4"/><circle cx="102" cy="76" r="4"/><circle cx="102" cy="88" r="4"/><circle cx="151" cy="142" r="4"/><circle cx="151" cy="154" r="4"/><circle cx="207" cy="72" r="4"/><circle cx="207" cy="84" r="4"/><circle cx="258" cy="138" r="4"/><circle cx="258" cy="150" r="4"/></g><path d="M82 198 Q150 171 218 198" fill="none" stroke="#ffc928" stroke-width="3" stroke-linecap="round"/><text x="150" y="215" fill="#dceeff" font-size="12" text-anchor="middle">CLOUD • NETWORK • DATA</text></svg>`}
function renderNavigation(){const side=$('#sideNav'),top=$('#topNav');side.innerHTML='';top.innerHTML='';topics.forEach((topic,i)=>{const active=currentTopic===topic.id;const sideBtn=document.createElement('button');sideBtn.className=`side-link${active?' active':''}`;sideBtn.dataset.topic=topic.id;sideBtn.innerHTML=`<span class="nav-icon" style="color:${topic.color}">${topic.icon}</span><span>${escapeHtml(tr(topic.title))}<small>${escapeHtml(tr(topic.short))}</small></span><span class="arrow">›</span>`;side.append(sideBtn);const topBtn=document.createElement('button');topBtn.className=`topic-pill${active?' active':''}`;topBtn.dataset.topic=topic.id;topBtn.textContent=`${String(i+1).padStart(2,'0')} · ${tr(topic.title)}`;top.append(topBtn)});$('#homeBtn').classList.toggle('active',currentTopic==='home');$('#glossaryBtn').style.background=currentTopic==='glossary'?'color-mix(in srgb,var(--blue) 12%,var(--panel))':''}
function goTopic(id){currentTopic=id;safeSet('cc-topic',id);renderNavigation();renderContent();$('#content').focus({preventScroll:true});window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function renderHome(){const s=ui[language];return `<section class="hero"><div><div class="eyebrow">IBB UNIVERSITY · INFORMATION TECHNOLOGY</div><h1>${escapeHtml(s.welcome)}</h1><div class="english-title">${language==='ar'?'Cloud Computing — الحوسبة السحابية':'Cloud Computing — الحوسبة السحابية'}</div><p>${escapeHtml(s.startDesc)}</p><div class="hero-actions"><button class="primary-btn" data-action="first">${escapeHtml(s.explore)}　›</button><button class="secondary-btn" data-action="glossary">${escapeHtml(s.openGlossary)}</button></div></div><div class="hero-graphic">${iconSvg()}</div></section><div class="stats"><div class="stat-card"><strong>13</strong><span>${escapeHtml(s.lessons)}</span></div><div class="stat-card"><strong>${glossary.length}+</strong><span>${escapeHtml(s.terms)}</span></div><div class="stat-card"><strong>AR / EN</strong><span>${escapeHtml(s.languages)}</span></div></div><h2 class="section-title">${escapeHtml(s.courseMap)}</h2><p class="section-intro">${escapeHtml(s.courseMapDesc)}</p><div class="topic-grid">${topics.map((x,i)=>`<button class="topic-card" data-topic="${x.id}" style="--card-color:${x.color}"><span class="card-top"><span class="card-icon">${x.icon}</span><strong>${String(i+1).padStart(2,'0')}. ${escapeHtml(tr(x.title))}</strong></span><small>${escapeHtml(tr(x.short))}</small><p>${escapeHtml(tr(x.desc))}</p></button>`).join('')}</div><h2 class="section-title">${escapeHtml(s.learningPath)}</h2><p class="section-intro">${escapeHtml(s.learningPathDesc)}</p><div class="diagram"><div class="flow-row">${[t('المفاهيم','Concepts'),t('البنية','Infrastructure'),t('الشبكات والأمن','Network & security'),t('الحاويات والنشر','Containers & deploy'),t('المراقبة والأتمتة','Operate & automate')].map((x,i)=>`${i?'<span class="flow-arrow">←</span>':''}<div class="flow-node">${escapeHtml(tr(x))}</div>`).join('')}</div></div>`}
function renderTable(table){return `<div class="table-wrap"><table class="data-table"><thead><tr>${table.headers.map(h=>`<th>${escapeHtml(tr(h))}</th>`).join('')}</tr></thead><tbody>${table.rows.map(row=>`<tr>${row.map(cell=>`<td>${escapeHtml(tr(cell))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function renderList(items,ordered=false){const tag=ordered?'ol':'ul';return `<${tag}>${items.map(item=>`<li>${escapeHtml(tr(item))}</li>`).join('')}</${tag}>`}
function renderCode(code){return `${code.label?`<div class="code-label">${escapeHtml(tr(code.label))}</div>`:''}<pre><code>${escapeHtml(code.text)}</code></pre>`}
function renderQA(qa){return qa.map(([q,a])=>`<details class="qa-item"><summary>${escapeHtml(tr(q))}</summary><p>${escapeHtml(tr(a))}</p></details>`).join('')}
function diagramSvg(kind){const rtl=language==='ar';const labels={ar:{user:'المستخدم / المتصفح',dns:'DNS',lb:'موازن الحمل',app:'طبقة التطبيق',db:'قاعدة بيانات خاصة',store:'تخزين الملفات',internet:'الإنترنت',vpc:'شبكة افتراضية VPC/VNet',subnet:'شبكة عامة',private:'شبكة خاصة',vm:'آلة افتراضية',hyper:'Hypervisor',hardware:'العتاد الفيزيائي',host:'Host OS',guest:'Guest OS',image:'Image',container:'Container',build:'Build',test:'Test',release:'Release',deploy:'Deploy',monitor:'مراقبة وسجلات',auth:'هوية وصلاحيات',api:'Backend API',meta:'Metadata DB',obj:'Object Storage',search:'بحث وفهرسة',backup:'نسخ احتياطي',review:'مراجعة المشرف',upload:'رفع الملف',code:'Code',plan:'Plan',apply:'Apply',infra:'موارد البنية',alerts:'تنبيهات',metrics:'Metrics',logs:'Logs',trace:'Traces',key:'مفاتيح وصلاحيات'},en:{user:'User / Browser',dns:'DNS',lb:'Load balancer',app:'Application tier',db:'Private database',store:'Object storage',internet:'Internet',vpc:'VPC / VNet',subnet:'Public subnet',private:'Private subnet',vm:'Virtual machine',hyper:'Hypervisor',hardware:'Physical hardware',host:'Host OS',guest:'Guest OS',image:'Image',container:'Container',build:'Build',test:'Test',release:'Release',deploy:'Deploy',monitor:'Logs & monitoring',auth:'Identity & access',api:'Backend API',meta:'Metadata DB',obj:'Object storage',search:'Search index',backup:'Backup',review:'Reviewer approval',upload:'File upload',code:'Code',plan:'Plan',apply:'Apply',infra:'Infrastructure',alerts:'Alerts',metrics:'Metrics',logs:'Logs',trace:'Traces',key:'Keys & permissions'}}[language];
const node=(x,y,w,h,label,fill='#123e78')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" fill="${fill}" stroke="#67b8ff" stroke-width="1.5"/><text x="${x+w/2}" y="${y+h/2+5}" text-anchor="middle" font-size="13" fill="#fff">${escapeHtml(label)}</text>`;
const line=(x1,y1,x2,y2)=>`<path d="M${x1} ${y1} L${x2} ${y2}" stroke="#f4be2b" stroke-width="2.5" fill="none" marker-end="url(#arrow)"/>`;
let body='';
if(kind==='network'){body=node(18,35,110,48,labels.user,'#195da5')+node(168,35,90,48,labels.dns)+node(298,35,125,48,labels.lb)+node(464,35,130,48,labels.app)+node(410,145,150,52,labels.db,'#125e52')+node(230,145,145,52,labels.store,'#6a3e9b')+node(18,145,150,52,labels.internet,'#4d5673')+line(128,59,168,59)+line(258,59,298,59)+line(423,59,464,59)+line(530,83,485,145)+line(494,83,302,145)+`<text x="300" y="225" text-anchor="middle" fill="currentColor" font-size="12">${rtl?'القاعدة لا تستقبل اتصالًا مباشرًا من الإنترنت':'Database has no direct public ingress'}</text>`}
else if(kind==='infra'){body=node(25,35,145,55,labels.user)+node(215,35,150,55,labels.lb)+node(410,35,150,55,labels.app)+node(70,145,160,55,labels.db,'#125e52')+node(330,145,160,55,labels.store,'#6a3e9b')+line(170,62,215,62)+line(365,62,410,62)+line(470,90,160,145)+line(480,90,410,145)+`<text x="300" y="230" text-anchor="middle" fill="currentColor" font-size="12">${rtl?'المراقبة والهوية والنسخ الاحتياطي تمتد عبر الطبقات':'Monitoring, identity, and backup span all layers'}</text>`}
else if(kind==='virtual'){body=node(25,35,550,45,labels.hardware,'#4d5673')+node(25,100,550,42,labels.hyper,'#164d8e')+node(25,165,165,50,`${labels.vm} 1`)+node(218,165,165,50,`${labels.vm} 2`)+node(410,165,165,50,`${labels.vm} 3`)+`<text x="107" y="195" fill="#fff" font-size="12" text-anchor="middle">${escapeHtml(labels.guest)}</text><text x="300" y="195" fill="#fff" font-size="12" text-anchor="middle">${escapeHtml(labels.guest)}</text><text x="492" y="195" fill="#fff" font-size="12" text-anchor="middle">${escapeHtml(labels.guest)}</text>`+line(300,80,300,100)+line(105,142,105,165)+line(300,142,300,165)+line(490,142,490,165) }
else if(kind==='docker'){body=node(20,45,115,60,labels.code,'#4d5673')+node(175,45,115,60,'Dockerfile')+node(330,45,115,60,labels.image,'#164d8e')+node(485,45,115,60,labels.container,'#12634f')+line(135,75,175,75)+line(290,75,330,75)+line(445,75,485,75)+node(180,150,270,48,'Registry / Deployment','#6a3e9b')+line(542,105,410,150)+`<text x="300" y="230" text-anchor="middle" fill="currentColor" font-size="12">${rtl?'المنفذ الداخلي يجب أن يطابق التطبيق':'Container port must match the application'}</text>`}
else if(kind==='cicd'){body=node(20,55,100,55,labels.code,'#4d5673')+node(145,55,100,55,labels.build)+node(270,55,100,55,labels.test,'#12634f')+node(395,55,100,55,labels.release,'#6a3e9b')+node(520,55,100,55,labels.deploy,'#145b45')+line(120,82,145,82)+line(245,82,270,82)+line(370,82,395,82)+line(495,82,520,82)+node(205,155,240,45,labels.monitor,'#4d5673')+line(570,110,430,155)+`<text x="300" y="230" text-anchor="middle" fill="currentColor" font-size="12">${rtl?'بوابة الموافقة وخطة التراجع قبل الإنتاج':'Approval gates and rollback plan before production'}</text>`}
else if(kind==='repository'||kind==='provider-architecture'){body=node(10,35,105,50,labels.user,'#4d5673')+node(150,35,115,50,labels.api)+node(310,20,130,50,labels.meta,'#125e52')+node(310,95,130,50,labels.obj,'#6a3e9b')+node(475,20,140,50,labels.search,'#4d5673')+node(475,95,140,50,labels.backup,'#4d5673')+line(115,60,150,60)+line(265,50,310,45)+line(265,65,310,120)+line(440,45,475,45)+line(440,120,475,120)+`<text x="330" y="195" text-anchor="middle" fill="currentColor" font-size="12">${rtl?'التحقق من الصلاحيات قبل إصدار روابط الملفات':'Authorize before issuing file access URLs'}</text>`}
else if(kind==='erd'){body=node(25,25,150,50,'Users','#195da5')+node(230,25,170,50,'ResearchPapers','#125e52')+node(450,25,150,50,'Categories','#6a3e9b')+node(35,140,150,50,'PaperVersions','#6a3e9b')+node(230,140,170,50,'Reviews','#a4510a')+node(450,140,150,50,'Authors','#195da5')+line(175,50,230,50)+line(400,50,450,50)+line(300,75,300,140)+line(230,165,185,165)+line(400,165,450,165)+`<text x="300" y="225" text-anchor="middle" fill="currentColor" font-size="12">${rtl?'PaperAuthors يربط الأبحاث بالمؤلفين بعلاقة متعدد إلى متعدد':'PaperAuthors joins papers and authors in a many-to-many relation'}</text>`}
else if(kind==='upload'){body=node(20,40,125,55,labels.user,'#4d5673')+node(180,40,125,55,labels.api)+node(340,40,125,55,labels.obj,'#6a3e9b')+node(500,40,125,55,labels.meta,'#125e52')+line(145,68,180,68)+line(305,68,340,68)+line(465,68,500,68)+node(200,145,300,48,labels.review,'#a4510a')+line(560,95,440,145)+`<text x="300" y="225" text-anchor="middle" fill="currentColor" font-size="12">${rtl?'الحالة Pending Review حتى قرار المراجع':'Status remains Pending Review until reviewer decision'}</text>`}
else if(kind==='automation'){body=node(20,45,120,55,labels.code,'#4d5673')+node(180,45,120,55,labels.plan)+node(340,45,120,55,labels.apply,'#a4510a')+node(500,45,120,55,labels.infra,'#12634f')+line(140,72,180,72)+line(300,72,340,72)+line(460,72,500,72)+node(190,150,260,48,labels.monitor,'#6a3e9b')+line(560,100,450,150)+`<text x="300" y="230" text-anchor="middle" fill="currentColor" font-size="12">${rtl?'راجع الخطة والكلفة والصلاحيات قبل التنفيذ':'Review plan, cost, and permissions before applying'}</text>`}
else if(kind==='security'){body=node(20,45,170,60,labels.auth,'#195da5')+node(230,45,170,60,labels.key,'#a4510a')+node(440,45,170,60,'Least privilege','#12634f')+line(190,75,230,75)+line(400,75,440,75)+node(125,155,380,48,'Confidentiality • Integrity • Availability','#4d5673')+line(315,105,315,155)}
else if(kind==='storage'){body=node(20,45,170,65,'Object Storage','#6a3e9b')+node(230,45,170,65,'Metadata Database','#125e52')+node(440,45,170,65,'Application API','#195da5')+line(190,78,230,78)+line(400,78,440,78)+`<text x="300" y="165" text-anchor="middle" fill="currentColor" font-size="13">${rtl?'الملف في التخزين، والبيانات الوصفية والعلاقات في قاعدة البيانات':'File in object storage; metadata and relationships in database'}</text>`}
else {body=node(20,60,140,60,'Client')+node(230,60,140,60,'Service')+node(440,60,140,60,'Resources')+line(160,90,230,90)+line(370,90,440,90)}
return `<figure class="diagram"><svg viewBox="0 0 640 250" role="img" aria-label="${escapeHtml((language==='ar'?'مخطط توضيحي: ':'Diagram: ')+kind)}"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#f4be2b"/></marker></defs>${body}</svg><figcaption>${rtl?'مخطط مفاهيمي تعليمي؛ أسماء الخدمات وتفاصيل التنفيذ تختلف حسب المزود والتكوين.':'Conceptual teaching diagram; service names and implementation details vary by provider and configuration.'}</figcaption></figure>`}
function renderSection(section,i){let body='';if(section.p)body+=`<p>${escapeHtml(tr(section.p))}</p>`;if(section.list)body+=renderList(section.list,section.ordered);if(section.table)body+=renderTable(section.table);if(section.diagram)body+=diagramSvg(section.diagram);if(section.code)body+=renderCode(section.code);if(section.callout)body+=`<div class="callout">${escapeHtml(tr(section.callout))}</div>`;if(section.qa)body+=renderQA(section.qa);if(section.refs)body+=renderRefs(section.refs);return `<section class="lesson-section" id="section-${i}"><h2>${escapeHtml(tr(section.h))}</h2>${body}</section>`}
function renderRefs(refs){return `<ul class="source-list">${refs.map(([name,url])=>`<li><a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(name)} ↗</a></li>`).join('')}</ul>`}
function renderTopic(topic){if(!topic)return `<div class="empty-state">${escapeHtml(ui[language].noTopic)}</div>`;const index=topics.findIndex(x=>x.id===topic.id);const s=ui[language];return `<header class="topic-head"><div class="breadcrumb">${escapeHtml(s.homeBreadcrumb)} / ${escapeHtml(tr(topic.title))}</div><h1>${escapeHtml(tr(topic.title))}</h1><div class="subhead">${escapeHtml(topic.title.en)}</div><p>${escapeHtml(tr(topic.desc))}</p><div class="progress-line" aria-label="${escapeHtml(s.courseProgress)}"><span style="width:${Math.round((index+1)/topics.length*100)}%"></span></div><div class="small-muted">${escapeHtml(s.topic)} ${index+1} ${escapeHtml(s.of)} ${topics.length}</div></header><div class="content-grid"><div class="lesson-body">${topic.sections.map(renderSection).join('')}<section class="lesson-section"><h2>${escapeHtml(s.references)}</h2>${renderRefs(topic.refs)}</section><nav class="lesson-nav" aria-label="Lesson navigation"><button class="nav-button" data-action="previous" ${index===0?'disabled':''}>← ${escapeHtml(s.previous)}</button><button class="nav-button home" data-action="home">⌂ ${escapeHtml(s.homeBtn)}</button><button class="nav-button" data-action="next" ${index===topics.length-1?'disabled':''}>${escapeHtml(s.next)} →</button></nav></div><aside class="lesson-aside"><strong>${escapeHtml(language==='ar'?'داخل هذا الموضوع':'In this topic')}</strong><nav>${topic.sections.map((section,i)=>`<a href="#section-${i}">${escapeHtml(tr(section.h))}</a>`).join('')}<a href="#" data-action="refs">${escapeHtml(s.references)}</a></nav></aside></div>`}
function renderGlossary(){const s=ui[language];const cats=[...new Set(glossary.map(x=>x.category))];const filtered=glossary.filter(x=>(glossaryCategory==='all'||x.category===glossaryCategory)&&[x.en,x.ar,x.abbr,x.descAr,x.descEn].some(v=>String(v).toLowerCase().includes(glossaryQuery.toLowerCase())));return `<header class="topic-head"><div class="breadcrumb">${escapeHtml(s.homeBreadcrumb)} / ${escapeHtml(s.glossary)}</div><h1>${escapeHtml(s.glossaryHeading)}</h1><div class="subhead">${escapeHtml(s.glossarySub)}</div><p>${escapeHtml(s.glossaryIntro)}</p></header><div class="glossary-tools"><input id="glossarySearch" type="search" value="${escapeHtml(glossaryQuery)}" placeholder="${escapeHtml(s.search)}" aria-label="${escapeHtml(s.search)}"><select id="glossaryCategory" aria-label="${escapeHtml(s.category)}"><option value="all">${escapeHtml(s.category)}</option>${cats.map(c=>`<option value="${escapeHtml(c)}" ${glossaryCategory===c?'selected':''}>${escapeHtml(c)}</option>`).join('')}</select></div><p class="small-muted">${escapeHtml(s.termsCount)}: ${filtered.length} / ${glossary.length}</p><div class="glossary-grid" id="glossaryGrid">${filtered.map(term=>`<article class="term-card"><div class="term-en">${escapeHtml(term.en)}${term.abbr&&term.abbr!==term.en?` <span class="badge">${escapeHtml(term.abbr)}</span>`:''}</div><div class="term-ar">${escapeHtml(term.ar)}</div><div class="term-category">${escapeHtml(term.category)}</div><p>${escapeHtml(language==='ar'?term.descAr:term.descEn)}</p><details><summary>${escapeHtml(language==='ar'?'التعريف بالإنجليزية':'Arabic definition')}</summary><p>${escapeHtml(language==='ar'?term.descEn:term.descAr)}</p></details></article>`).join('')||`<div class="empty-state">${escapeHtml(s.noResults)}</div>`}</div>`}
function renderContent(){const content=$('#content');if(currentTopic==='home')content.innerHTML=renderHome();else if(currentTopic==='glossary')content.innerHTML=renderGlossary();else content.innerHTML=renderTopic(topics.find(x=>x.id===currentTopic));}
function onClick(event){const topicButton=event.target.closest('[data-topic]');if(topicButton){goTopic(topicButton.dataset.topic);return}const actionButton=event.target.closest('[data-action]');if(!actionButton)return;const action=actionButton.dataset.action;if(action==='first')goTopic(topics[0].id);else if(action==='glossary')goTopic('glossary');else if(action==='home')goTopic('home');else if(action==='next'||action==='previous'){const index=topics.findIndex(x=>x.id===currentTopic);const next=index+(action==='next'?1:-1);if(next>=0&&next<topics.length)goTopic(topics[next].id)}else if(action==='refs'){$$('.lesson-section').at(-1)?.scrollIntoView({behavior:'smooth',block:'start'})}}
function updateGlossary(){const search=$('#glossarySearch');const select=$('#glossaryCategory');if(search)glossaryQuery=search.value;if(select)glossaryCategory=select.value;renderContent();const nextSearch=$('#glossarySearch');if(nextSearch){nextSearch.focus({preventScroll:true});nextSearch.setSelectionRange(nextSearch.value.length,nextSearch.value.length)}}
$('#homeBtn').addEventListener('click',()=>goTopic('home'));$('#glossaryBtn').addEventListener('click',()=>goTopic('glossary'));$('#arabicBtn').addEventListener('click',()=>setLanguage('ar'));$('#englishBtn').addEventListener('click',()=>setLanguage('en'));$('#themeBtn').addEventListener('click',()=>setTheme(theme==='dark'?'light':'dark'));$('#content').addEventListener('click',onClick);$('#sideNav').addEventListener('click',onClick);$('#topNav').addEventListener('click',onClick);$('#content').addEventListener('input',e=>{if(e.target.id==='glossarySearch'){const start=e.target.selectionStart;glossaryQuery=e.target.value;const scroll=window.scrollY;renderContent();const input=$('#glossarySearch');input.focus({preventScroll:true});input.setSelectionRange(start,start);window.scrollTo(0,scroll)}});$('#content').addEventListener('change',e=>{if(e.target.id==='glossaryCategory'){glossaryCategory=e.target.value;renderContent()}});
document.addEventListener('keydown',e=>{if(e.altKey&&e.key==='ArrowRight'){const i=topics.findIndex(x=>x.id===currentTopic);if(i>0)goTopic(topics[i-1].id)}if(e.altKey&&e.key==='ArrowLeft'){const i=topics.findIndex(x=>x.id===currentTopic);if(i>=0&&i<topics.length-1)goTopic(topics[i+1].id)}if(e.key==='Escape'&&currentTopic!=='home')goTopic('home')});
setTheme(theme);setLanguage(language);goTopic(currentTopic);
